using System.Globalization;using System.IO;using System.Reflection;using System.Text;using System.Windows;using System.Windows.Threading;using YukkuriMovieMaker.Plugin;using YukkuriMovieMaker.Project;using YukkuriMovieMaker.Project.Items;
namespace Ymm4NonzeroTimestampProbe;
public sealed class PluginEntry:ILocalizePlugin{public string Name=>"Chat Native Work Lab — Recording Archive Nonzero Timestamp";public void SetCulture(CultureInfo c)=>Probe.Schedule();}
internal static class Probe
{
 static bool once;static string output="",fixture="";
 public static void Schedule(){var d=Environment.GetEnvironmentVariable("CNWL_YMM4_NONZERO_TS_DIR");var f=Environment.GetEnvironmentVariable("CNWL_YMM4_NONZERO_TS_FIXTURE");if(once||string.IsNullOrWhiteSpace(d)||string.IsNullOrWhiteSpace(f))return;once=true;output=Path.GetFullPath(d);fixture=Path.GetFullPath(f);Directory.CreateDirectory(output);Application.Current.Dispatcher.BeginInvoke(new Action(Start),DispatcherPriority.ApplicationIdle);}
 static void Start(){var n=0,created=0;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(400)};timer.Tick+=async(_,_)=>{try{foreach(Window w in Application.Current.Windows){var root=w.DataContext;if(root?.GetType().FullName!="YukkuriMovieMaker.ViewModels.MainViewModel")continue;var active=root.GetType().GetProperty("ActiveTimelineViewModel")?.GetValue(root);if(active==null&&created++==0){root.GetType().GetMethod("CreateProject",Type.EmptyTypes)?.Invoke(root,null);break;}var tl=active?.GetType().GetField("timeline",BindingFlags.Instance|BindingFlags.NonPublic)?.GetValue(active) as Timeline;if(tl==null)continue;timer.Stop();await Run(tl);return;}if(++n>100)throw new TimeoutException();}catch(Exception ex){timer.Stop();File.WriteAllLines(Path.Combine(output,"result.txt"),["status=FAIL_EXCEPTION","detail="+ex.GetBaseException().Message],new UTF8Encoding(false));}};timer.Start();}
 static async Task Run(Timeline tl){var item=new VideoItem(fixture){Frame=0,Layer=10,Remark="CNWL_NONZERO_TS"};if(!tl.TryAddItems([item],0,10))throw new Exception("add failed");await Idle();await Idle();File.WriteAllLines(Path.Combine(output,"result.txt"),["status=PASS_NONZERO_TIMESTAMP_OBSERVATION","content_length="+item.ContentLength.TotalSeconds.ToString("R",CultureInfo.InvariantCulture),"original_content_length="+item.OriginalContentLength.TotalSeconds.ToString("R",CultureInfo.InvariantCulture),"content_length_positive="+(item.ContentLength>TimeSpan.Zero)],new UTF8Encoding(false));}
 static async Task Idle()=>await Application.Current.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle).Task;
}
